CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS admins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, name text NOT NULL, phone text, created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE admins ADD COLUMN IF NOT EXISTS password_hash text;
CREATE TABLE IF NOT EXISTS admin_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admin_id uuid NOT NULL REFERENCES admins ON DELETE CASCADE, expires_at timestamptz NOT NULL, trusted_until timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS admin_sessions_admin_idx ON admin_sessions(admin_id, expires_at);
CREATE TABLE IF NOT EXISTS otp_verifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), admin_id uuid NOT NULL REFERENCES admins ON DELETE CASCADE, otp_hash text NOT NULL, expires_at timestamptz NOT NULL, attempts int NOT NULL DEFAULT 0, last_sent_at timestamptz NOT NULL DEFAULT now(), used_at timestamptz);
CREATE INDEX IF NOT EXISTS otp_admin_idx ON otp_verifications(admin_id, expires_at DESC);
CREATE TABLE IF NOT EXISTS categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text UNIQUE NOT NULL, description text NOT NULL DEFAULT '', image text, status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')), sort_order int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, slug text UNIQUE NOT NULL, description text NOT NULL DEFAULT '', category_id uuid REFERENCES categories ON DELETE SET NULL, status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','INACTIVE')), featured boolean NOT NULL DEFAULT false, seo_title text, seo_description text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS products_status_created_idx ON products(status, created_at DESC);
CREATE INDEX IF NOT EXISTS products_category_idx ON products(category_id);
CREATE TABLE IF NOT EXISTS product_variants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products ON DELETE CASCADE, sku text UNIQUE NOT NULL, colour text NOT NULL, size text NOT NULL, price numeric(12,2) NOT NULL CHECK(price >= 0), availability text NOT NULL DEFAULT 'AVAILABLE' CHECK(availability IN ('AVAILABLE','UNAVAILABLE')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(product_id, colour, size));
CREATE INDEX IF NOT EXISTS variants_filter_idx ON product_variants(colour,size,price,availability,product_id);
CREATE TABLE IF NOT EXISTS product_images(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products ON DELETE CASCADE, storage_path text NOT NULL UNIQUE, public_url text NOT NULL, alt_text text NOT NULL DEFAULT '', sort_order int NOT NULL DEFAULT 0, is_primary boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS order_inquiries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reference_number text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','CONTACTED','CONFIRMED','SOLD','CANCELLED')), channel text NOT NULL DEFAULT 'WHATSAPP', subtotal numeric(12,2) NOT NULL, total numeric(12,2) NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS inquiries_status_created_idx ON order_inquiries(status,created_at DESC);
CREATE TABLE IF NOT EXISTS order_inquiry_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_inquiry_id uuid NOT NULL REFERENCES order_inquiries ON DELETE CASCADE, product_id uuid REFERENCES products ON DELETE SET NULL, variant_id uuid REFERENCES product_variants ON DELETE SET NULL, product_name_snapshot text NOT NULL, colour_snapshot text NOT NULL, size_snapshot text NOT NULL, sku_snapshot text NOT NULL, unit_price_snapshot numeric(12,2) NOT NULL, quantity int NOT NULL CHECK(quantity BETWEEN 1 AND 99), subtotal numeric(12,2) NOT NULL);
CREATE TABLE IF NOT EXISTS analytics_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL CHECK(event_type IN ('PRODUCT_VIEW','ADD_TO_CART','REMOVE_FROM_CART','WHATSAPP_ORDER_INITIATED','SEARCH')), product_id uuid REFERENCES products ON DELETE SET NULL, variant_id uuid REFERENCES product_variants ON DELETE SET NULL, anonymous_id text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS analytics_type_date_idx ON analytics_events(event_type,created_at DESC);
CREATE INDEX IF NOT EXISTS analytics_product_date_idx ON analytics_events(product_id,created_at DESC);
